# Let's carefully check each transformation
inputs = ['gyiev', 'ah', 'cvykb', 'yyyjch', 'gzdd']
outputs = ['gyiev', 'ah', 'cvydfuvb', 'yyyjch', 'gdcd']

print("Analyzing each input-output pair:")
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    print(f"Pair {i+1}: '{inp}' → '{outp}'")
    if inp == outp:
        print("  No change")
    else:
        # Find differing positions
        min_len = min(len(inp), len(outp))
        diffs = []
        for j in range(max(len(inp), len(outp))):
            if j >= len(inp):
                diffs.append(f"pos {j}: added '{outp[j]}'")
            elif j >= len(outp):
                diffs.append(f"pos {j}: removed '{inp[j]}'")  
            elif inp[j] != outp[j]:
                diffs.append(f"pos {j}: '{inp[j]}' → '{outp[j]}'")
        print("  Differences:", ", ".join(diffs))
    print()

